{"implementation": "def solve(case):
    payload = case["payload"]
    attempts = payload["attempts"]
    max_attempts = payload["max_attempts"]

    if not attempts:
        return {"decision": "retry", "next_index": 1, "memory_update": {}}

    last = attempts[-1]
    if last["success"]:
        return {"decision": "stop", "next_index": None, "memory_update": {}}

    if len(attempts) >= max_attempts:
        return {"decision": "stop", "next_index": None, "memory_update": {}}

    last_sig = last["failure_signature"]
    for prev in attempts[:-1]:
        if prev["failure_signature"] == last_sig:
            return {"decision": "stop", "next_index": None, "memory_update": {}}

    next_index = len(attempts) + 1
    reflection = last["reflection"]
    memory_update = {"reflection": reflection, "signature": last_sig}
    return {"decision": "retry", "next_index": next_index, "memory_update": memory_update}"}
